import { QueryBuilder } from './query-builder.js';
import { AuthManager } from './auth.js';
import { StorageManager } from './storage.js';
import { RealtimeManager } from './realtime.js';
import { RpcManager } from './rpc.js';
import { TemplatesManager } from './templates.js';
import type { MatuDBConfig, QueryResult } from './types.js';
import { createClient as createSupabaseClient } from '@supabase/supabase-js';

export type { MatuDBConfig, QueryResult, MatuDBError, AuthResult, AuthUser, AuthSession, AuthChangeEvent, AuthStateChangeCallback, RealtimeEvent, RealtimePayload, StorageFile, StorageResult, FilterOperator } from './types.js';
export { QueryBuilder } from './query-builder.js';
export { AuthManager } from './auth.js';
export { StorageManager } from './storage.js';
export { RealtimeManager, RealtimeChannel } from './realtime.js';
export { RpcManager } from './rpc.js';
export { TemplatesManager } from './templates.js';

/**
 * Utility to get environment variables across Node, Vite, etc.
 */
function getEnv(name: string): string | undefined {
    // Node.js
    if (typeof process !== 'undefined' && process.env && process.env[name]) {
        return process.env[name];
    }
    // Vite / Next.js (usually prefixed or in import.meta.env)
    // @ts-ignore
    if (typeof import.meta !== 'undefined' && import.meta.env && import.meta.env[name]) {
        // @ts-ignore
        return import.meta.env[name];
    }
    // Browser global
    // @ts-ignore
    if (typeof window !== 'undefined' && window[name]) {
        // @ts-ignore
        return window[name];
    }
    return undefined;
}

/**
 * Auto-detect configuration from environment variables.
 */
function getEnvConfig(): MatuDBConfig | null {
    const url = getEnv('MATUDB_URL') || getEnv('VITE_MATUDB_URL') || getEnv('NEXT_PUBLIC_MATUDB_URL');
    const apiKey = getEnv('MATUDB_API_KEY') || getEnv('VITE_MATUDB_API_KEY') || getEnv('NEXT_PUBLIC_MATUDB_API_KEY');
    const projectId = getEnv('MATUDB_PROJECT_ID') || getEnv('VITE_MATUDB_PROJECT_ID') || getEnv('NEXT_PUBLIC_MATUDB_PROJECT_ID') || 'default';
    const useSupabase = (getEnv('MATUDB_USE_SUPABASE') || getEnv('VITE_MATUDB_USE_SUPABASE')) === 'true';

    if (url && apiKey) {
        return { url, apiKey, projectId, useSupabase };
    }
    return null;
}

/**
 * The main MatuDB client — mirrors the Supabase client API.
 */
export class MatuDBClient {
    readonly config: MatuDBConfig;

    /** Auth module — equivalent to supabase.auth */
    readonly auth: AuthManager;

    /** Storage module — equivalent to supabase.storage */
    readonly storage: StorageManager;

    /** Realtime manager — use .channel() to subscribe to table changes */
    readonly realtime: RealtimeManager;

    /** Email Templates module — send programmed emails with placeholders */
    readonly templates: TemplatesManager;

    private readonly _rpc: RpcManager;
    private readonly _supabase?: any;

    constructor(config: MatuDBConfig) {
        this.config = config;

        if (config.useSupabase) {
            this._supabase = createSupabaseClient(config.url, config.apiKey);
            this.auth = this._supabase.auth;
            this.storage = this._supabase.storage;
            this.realtime = this._supabase;
            this._rpc = this._supabase;
        } else {
            this.auth = new AuthManager(config);
            this.storage = new StorageManager(config);
            this.realtime = new RealtimeManager(config);
            this._rpc = new RpcManager(config, () => this.auth.getAccessToken());
        }
        this.templates = new TemplatesManager(config);
    }

    /**
     * Create a QueryBuilder for a table.
     */
    from<T = any>(table: string): any {
        if (this._supabase) {
            return this._supabase.from(table);
        }
        return new QueryBuilder<T>(table, this.config);
    }

    /**
     * Create a realtime channel.
     */
    channel<T = any>(name: string): any {
        if (this._supabase) {
            return this._supabase.channel(name);
        }
        return this.realtime.channel<T>(name);
    }

    /**
     * Remove a channel.
     */
    removeChannel(channel: any): void {
        if (this._supabase) {
            this._supabase.removeChannel(channel);
        } else {
            this.realtime.removeChannel(channel);
        }
    }

    /**
     * Remove all channels.
     */
    removeAllChannels(): void {
        if (this._supabase) {
            this._supabase.removeAllChannels();
        } else {
            this.realtime.removeAllChannels();
        }
    }

    /**
     * Execute a raw SQL query.
     */
    async rpc<T = any>(query: string, params?: Record<string, any>): Promise<QueryResult<T[]>> {
        if (this._supabase) {
            // In Supabase, rpc is for functions. For raw SQL, there isn't a direct equivalent,
            // but we'll try to call the rpc function if that's what's intended, or error out.
            return this._supabase.rpc(query, params);
        }
        return this._rpc.execute<T>(query, params);
    }
}

/**
 * Create a MatuDB client instance.
 *
 * If no config is provided, it will attempt to read from environment variables:
 * MATUDB_URL, MATUDB_API_KEY, MATUDB_PROJECT_ID, MATUDB_USE_SUPABASE.
 */
export function createClient(config?: Partial<MatuDBConfig>): MatuDBClient {
    const envConfig = getEnvConfig();
    const finalConfig = {
        url: config?.url || envConfig?.url || '',
        apiKey: config?.apiKey || envConfig?.apiKey || '',
        projectId: config?.projectId || envConfig?.projectId || 'default',
        useSupabase: config?.useSupabase ?? envConfig?.useSupabase ?? false,
    };

    if (!finalConfig.url || !finalConfig.apiKey) {
        console.warn(`MatuDBClient: Missing URL or API Key. [URL: ${!!finalConfig.url}, Key: ${!!finalConfig.apiKey}]. Ensure VITE_MATUDB_URL and VITE_MATUDB_API_KEY are set.`);
    }

    return new MatuDBClient(finalConfig);
}
