import type { MatuDBConfig, StorageResult, StorageFile, MatuDBError } from './types.js';

function toError(err: unknown): MatuDBError {
    if (err instanceof Error) return { message: err.message };
    return { message: 'Unknown error' };
}

/**
 * Storage module — mirrors supabase.storage.*
 *
 * Note: MatuDB storage doesn't have named "buckets" — all files are stored
 * per-project. The bucket name is accepted but ignored for compatibility.
 *
 * Usage:
 *   const { data, error } = await db.storage.upload('avatar.png', file);
 *   const { data } = await db.storage.list();
 *   const url = db.storage.getPublicUrl('avatar.png');
 */
export class StorageManager {
    private _config: MatuDBConfig;

    constructor(config: MatuDBConfig) {
        this._config = config;
    }

    /** Returns a bucket-scoped storage helper (bucket name is ignored — included for Supabase API parity) */
    from(_bucket: string): this {
        return this;
    }

    private _baseUrl(): string {
        return `${this._config.url}/api/projects/${this._config.projectId}/storage`;
    }

    private _authHeader(): Record<string, string> {
        return { apikey: this._config.apiKey };
    }

    /**
     * Upload a file.
     * @param path  Filename / path to use (used as the file name on the server)
     * @param file  File, Blob, or Buffer
     * @param options Optional { contentType, upsert }
     */
    async upload(
        path: string,
        file: File | Blob | Uint8Array | ArrayBuffer,
        _options?: { contentType?: string; upsert?: boolean }
    ): Promise<StorageResult<StorageFile>> {
        try {
            const formData = new FormData();

            if (file instanceof Blob || file instanceof File) {
                formData.append('file', file, path);
            } else {
                // Uint8Array / ArrayBuffer — wrap in Blob
                const blob = new Blob([file as any]);
                formData.append('file', blob, path);
            }

            const res = await fetch(`${this._baseUrl()}/upload`, {
                method: 'POST',
                headers: this._authHeader(),
                body: formData,
            });

            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'Upload failed' } };
            return { data: json.data?.file ?? json.data, error: null };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    /**
     * Download a file by filename.
     */
    async download(filename: string): Promise<StorageResult<Blob>> {
        try {
            const res = await fetch(`${this._baseUrl()}/${encodeURIComponent(filename)}`, {
                headers: this._authHeader(),
            });
            if (!res.ok) {
                const json = await res.json().catch(() => ({}));
                return { data: null, error: { message: json.message || 'Download failed' } };
            }
            const blob = await res.blob();
            return { data: blob, error: null };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    /**
     * List all files in the project storage.
     */
    async list(_prefix?: string, _options?: { limit?: number; offset?: number }): Promise<StorageResult<StorageFile[]>> {
        try {
            const res = await fetch(this._baseUrl(), {
                headers: this._authHeader(),
            });
            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'List failed' } };
            const files: StorageFile[] = json.data?.files ?? json.data ?? [];
            return { data: files, error: null };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    /**
     * Delete one or more files.
     */
    async remove(paths: string[]): Promise<StorageResult<StorageFile[]>> {
        const deleted: StorageFile[] = [];
        const errors: string[] = [];

        for (const p of paths) {
            try {
                const res = await fetch(`${this._baseUrl()}/${encodeURIComponent(p)}`, {
                    method: 'DELETE',
                    headers: this._authHeader(),
                });
                const json = await res.json();
                if (res.ok) {
                    deleted.push(json.data?.file ?? { name: p } as StorageFile);
                } else {
                    errors.push(json.message || `Failed to delete ${p}`);
                }
            } catch (err) {
                errors.push(err instanceof Error ? err.message : `Failed to delete ${p}`);
            }
        }

        if (errors.length > 0 && deleted.length === 0) {
            return { data: null, error: { message: errors.join(', ') } };
        }
        return { data: deleted, error: errors.length > 0 ? { message: errors.join(', ') } : null };
    }

    /**
     * Get the public URL for a file (no auth required if server serves it publicly).
     */
    getPublicUrl(filename: string): { data: { publicUrl: string } } {
        const publicUrl = `${this._baseUrl()}/${encodeURIComponent(filename)}`;
        return { data: { publicUrl } };
    }

    /**
     * Get storage stats (size & count).
     */
    async getStats(): Promise<StorageResult<{ total_size: number; total_files: number }>> {
        try {
            const res = await fetch(`${this._baseUrl()}/stats`, {
                headers: this._authHeader(),
            });
            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'Stats failed' } };
            return { data: json.data, error: null };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }
}
