import type {
    MatuDBConfig,
    AuthResult,
    AuthUser,
    AuthSession,
    AuthStateChangeCallback,
    AuthChangeEvent,
    MatuDBError,
} from './types.js';

const SESSION_KEY = 'matudb_session';

function toError(err: unknown): MatuDBError {
    if (err instanceof Error) return { message: err.message };
    return { message: 'Unknown error' };
}

/**
 * Auth module — mirrors supabase.auth.*
 *
 * Usage:
 *   const { data, error } = await db.auth.signInWithPassword({ email, password });
 *   const { data: { session } } = await db.auth.getSession();
 *   db.auth.onAuthStateChange((event, session) => { ... });
 */
export class AuthManager {
    private _config: MatuDBConfig;
    private _session: AuthSession | null = null;
    private _listeners: AuthStateChangeCallback[] = [];
    private _initialized = false;

    constructor(config: MatuDBConfig) {
        this._config = config;
        this._loadSession();
    }

    private _baseUrl(): string {
        return `${this._config.url}/api/projects/${this._config.projectId}/auth`;
    }

    private _headers(): Record<string, string> {
        return {
            'Content-Type': 'application/json',
            apikey: this._config.apiKey,
        };
    }

    private _loadSession(): void {
        try {
            const raw = typeof localStorage !== 'undefined'
                ? localStorage.getItem(SESSION_KEY)
                : null;
            if (raw) {
                const stored: AuthSession = JSON.parse(raw);
                // Check expiry
                if (stored.expires_at && Date.now() / 1000 < stored.expires_at) {
                    this._session = stored;
                } else {
                    localStorage.removeItem(SESSION_KEY);
                }
            }
        } catch {
            // no-op in non-browser environments
        }
        this._initialized = true;
    }

    private _saveSession(session: AuthSession | null): void {
        this._session = session;
        try {
            if (typeof localStorage === 'undefined') return;
            if (session) {
                localStorage.setItem(SESSION_KEY, JSON.stringify(session));
            } else {
                localStorage.removeItem(SESSION_KEY);
            }
        } catch {
            // no-op
        }
    }

    private _emit(event: AuthChangeEvent): void {
        for (const cb of this._listeners) {
            try { cb(event, this._session); } catch { /* no-op */ }
        }
    }

    private _buildSession(user: AuthUser, token: string): AuthSession {
        // Decode JWT to get expiry
        let expiresAt = Math.floor(Date.now() / 1000) + 86400; // default 24h
        try {
            const payload = JSON.parse(atob(token.split('.')[1]));
            if (payload.exp) expiresAt = payload.exp;
        } catch { /* no-op */ }

        return {
            access_token: token,
            token_type: 'bearer',
            expires_at: expiresAt,
            user,
        };
    }

    // ─── Public API ──────────────────────────────────────────────────────────

    async signUp({ email, password, options }: {
        email: string;
        password: string;
        options?: { data?: Record<string, any> };
    }): Promise<AuthResult> {
        try {
            const res = await fetch(`${this._baseUrl()}/register`, {
                method: 'POST',
                headers: this._headers(),
                body: JSON.stringify({ email, password, name: options?.data?.name }),
            });
            const json = await res.json();
            if (!res.ok) return { data: { user: null, session: null }, error: { message: json.message || 'Sign up failed' } };

            const session = this._buildSession(json.data.user, json.data.token);
            this._saveSession(session);
            this._emit('SIGNED_IN');
            return { data: { user: session.user, session }, error: null };
        } catch (err) {
            return { data: { user: null, session: null }, error: toError(err) };
        }
    }

    async signInWithPassword({ email, password }: { email: string; password: string }): Promise<AuthResult> {
        try {
            const res = await fetch(`${this._baseUrl()}/login`, {
                method: 'POST',
                headers: this._headers(),
                body: JSON.stringify({ email, password }),
            });
            const json = await res.json();
            if (!res.ok) return { data: { user: null, session: null }, error: { message: json.message || 'Sign in failed' } };

            const session = this._buildSession(json.data.user, json.data.token);
            this._saveSession(session);
            this._emit('SIGNED_IN');
            return { data: { user: session.user, session }, error: null };
        } catch (err) {
            return { data: { user: null, session: null }, error: toError(err) };
        }
    }

    async resetPasswordForEmail(email: string): Promise<{ data: any; error: MatuDBError | null }> {
        try {
            const res = await fetch(`${this._baseUrl()}/recover`, {
                method: 'POST',
                headers: this._headers(),
                body: JSON.stringify({ email }),
            });
            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'Error requesting recovery' } };
            return { data: json.data, error: null };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    async updateUser({ password }: { password: string }, { token }: { token?: string } = {}): Promise<AuthResult> {
        try {
            if (!token && !this._session) return { data: { user: null, session: null }, error: { message: 'Authentication required' } };

            const body: any = { password };
            if (token) body.token = token;

            const res = await fetch(`${this._baseUrl()}/${token ? 'reset' : 'user'}`, {
                method: token ? 'POST' : 'PATCH',
                headers: {
                    ...this._headers(),
                    ...(this._session ? { Authorization: `Bearer ${this._session.access_token}` } : {}),
                },
                body: JSON.stringify(body),
            });
            const json = await res.json();
            if (!res.ok) return { data: { user: null, session: null }, error: { message: json.message || 'Update failed' } };

            return { data: { user: json.data, session: null }, error: null };
        } catch (err) {
            return { data: { user: null, session: null }, error: toError(err) };
        }
    }

    async signOut(): Promise<{ error: MatuDBError | null }> {

        this._saveSession(null);
        this._emit('SIGNED_OUT');
        return { error: null };
    }

    async getSession(): Promise<{ data: { session: AuthSession | null }; error: MatuDBError | null }> {
        return { data: { session: this._session }, error: null };
    }

    async getUser(): Promise<{ data: { user: AuthUser | null }; error: MatuDBError | null }> {
        if (!this._session) return { data: { user: null }, error: null };

        try {
            const res = await fetch(`${this._baseUrl()}/user`, {
                headers: {
                    ...this._headers(),
                    Authorization: `Bearer ${this._session.access_token}`,
                },
            });
            const json = await res.json();
            if (!res.ok) return { data: { user: null }, error: { message: json.message || 'Failed to get user' } };
            return { data: { user: json.data?.user ?? json.data }, error: null };
        } catch (err) {
            // Fallback to local session user
            return { data: { user: this._session?.user ?? null }, error: null };
        }
    }

    onAuthStateChange(callback: AuthStateChangeCallback): { data: { subscription: { unsubscribe: () => void } } } {
        this._listeners.push(callback);

        // Immediately fire with current state
        if (this._initialized) {
            const event: AuthChangeEvent = this._session ? 'SIGNED_IN' : 'SIGNED_OUT';
            try { callback(event, this._session); } catch { /* no-op */ }
        }

        return {
            data: {
                subscription: {
                    unsubscribe: () => {
                        const idx = this._listeners.indexOf(callback);
                        if (idx !== -1) this._listeners.splice(idx, 1);
                    },
                },
            },
        };
    }

    /** Get the raw access token for use in Authorization headers */
    getAccessToken(): string | null {
        return this._session?.access_token ?? null;
    }
}
