import type { MatuDBConfig, QueryResult } from './types.js';

/**
 * TemplatesManager handles email automation using predefined templates.
 * Call templates directly using their unique slug/name.
 */
export class TemplatesManager {
    private readonly config: MatuDBConfig;

    constructor(config: MatuDBConfig) {
        this.config = config;
    }

    /**
     * Send an email using a predefined template.
     * 
     * @example
     * ```typescript
     * await db.templates.send('welcome-email', 'user@example.com', {
     *   name: 'John Doe',
     *   activation_link: 'https://myapp.com/activate'
     * });
     * ```
     * 
     * @param templateSlug The unique slug/name of the template configured in MatuDB Dashboard
     * @param to Recipient email address
     * @param variables Key-value pairs to replace placeholders in the template (e.g. {{name}})
     */
    async send(templateSlug: string, to: string, variables: Record<string, any> = {}): Promise<QueryResult<{ success: boolean; sentTo: string }>> {
        try {
            const response = await fetch(`${this.config.url}/projects/${this.config.projectId}/templates/send`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${this.config.apiKey}`, // Assuming API key can be used as Bearer for service calls
                    'apikey': this.config.apiKey
                },
                body: JSON.stringify({ templateSlug: templateSlug, to, variables }),
            });

            const result = await response.json();
            if (!response.ok) {
                return { data: null, error: { message: result.error || 'Failed to send email template' }, status: response.status };
            }

            return { data: result.data, error: null, status: response.status };
        } catch (err: any) {
            return { data: null, error: { message: err.message || 'Network error' } };
        }
    }
}
