import type {
    MatuDBConfig,
    QueryResult,
    MatuDBError,
    FilterEntry,
    FilterOperator,
    OrderEntry,
    CountOption,
} from './types.js';

function toError(err: unknown): MatuDBError {
    if (err instanceof Error) return { message: err.message };
    if (typeof err === 'string') return { message: err };
    return { message: 'Unknown error' };
}

/**
 * Supabase-compatible query builder for MatuDB.
 *
 * Usage:
 *   const { data, error } = await db.from('users').select('*').eq('active', true).limit(10);
 */
export class QueryBuilder<T = any> {
    private _config: MatuDBConfig;
    private _table: string;
    private _select: string = '*';
    private _filters: FilterEntry[] = [];
    private _orFilters: string[] = [];
    private _orders: OrderEntry[] = [];
    private _limit: number | null = null;
    private _offset: number | null = null;
    private _single: boolean = false;
    private _maybeSingle: boolean = false;
    private _count: CountOption | null = null;
    private _returning: 'minimal' | 'representation' = 'representation';

    constructor(table: string, config: MatuDBConfig) {
        this._table = table;
        this._config = config;
    }

    // ─── Column Selection ───────────────────────────────────────────────────

    select(columns: string = '*', options?: { count?: CountOption; head?: boolean }) {
        this._select = columns || '*';
        if (options?.count) this._count = options.count;
        return this;
    }

    // ─── Filter Operators ───────────────────────────────────────────────────

    eq(column: string, value: any) {
        this._filters.push({ column, operator: 'eq', value });
        return this;
    }

    neq(column: string, value: any) {
        this._filters.push({ column, operator: 'neq', value });
        return this;
    }

    gt(column: string, value: any) {
        this._filters.push({ column, operator: 'gt', value });
        return this;
    }

    gte(column: string, value: any) {
        this._filters.push({ column, operator: 'gte', value });
        return this;
    }

    lt(column: string, value: any) {
        this._filters.push({ column, operator: 'lt', value });
        return this;
    }

    lte(column: string, value: any) {
        this._filters.push({ column, operator: 'lte', value });
        return this;
    }

    like(column: string, pattern: string) {
        this._filters.push({ column, operator: 'like', value: pattern });
        return this;
    }

    ilike(column: string, pattern: string) {
        this._filters.push({ column, operator: 'ilike', value: pattern });
        return this;
    }

    in(column: string, values: any[]) {
        this._filters.push({ column, operator: 'in', value: values });
        return this;
    }

    is(column: string, value: true | false | null) {
        this._filters.push({ column, operator: 'is', value });
        return this;
    }

    /** Add a raw OR filter string, e.g. .or('age.gt.18,name.eq.Alice') */
    or(filters: string) {
        this._orFilters.push(filters);
        return this;
    }

    /** Negate a filter */
    not(column: string, operator: FilterOperator, value: any) {
        // For not, we prefix the operator with 'not_'
        this._filters.push({ column, operator: `not_${operator}` as FilterOperator, value });
        return this;
    }

    // ─── Modifiers ──────────────────────────────────────────────────────────

    order(column: string, options?: { ascending?: boolean; nullsFirst?: boolean }) {
        this._orders.push({
            column,
            ascending: options?.ascending ?? true,
            nullsFirst: options?.nullsFirst,
        });
        return this;
    }

    limit(count: number) {
        this._limit = count;
        return this;
    }

    range(from: number, to: number) {
        this._offset = from;
        this._limit = to - from + 1;
        return this;
    }

    single() {
        this._single = true;
        return this;
    }

    maybeSingle() {
        this._maybeSingle = true;
        return this;
    }

    /** Control what gets returned after mutations */
    select_returning(option: 'minimal' | 'representation') {
        this._returning = option;
        return this;
    }

    // ─── Build URL params ───────────────────────────────────────────────────

    private buildParams(): URLSearchParams {
        const params = new URLSearchParams();
        params.set('apikey', this._config.apiKey);

        if (this._select !== '*') params.set('select', this._select);
        if (this._limit !== null) params.set('limit', String(this._limit));
        if (this._offset !== null) params.set('offset', String(this._offset));

        for (const o of this._orders) {
            params.append('order', `${o.column}.${o.ascending ? 'asc' : 'desc'}`);
        }

        for (const f of this._filters) {
            // Format: column=operator.value
            let val: string;
            if (f.operator === 'in' && Array.isArray(f.value)) {
                val = `in.(${f.value.join(',')})`;
            } else if (f.operator === 'is') {
                val = `is.${f.value === null ? 'null' : String(f.value)}`;
            } else {
                val = `${f.operator}.${f.value}`;
            }
            params.append(f.column, val);
        }

        for (const or of this._orFilters) {
            params.append('or', or);
        }

        return params;
    }

    private get baseUrl(): string {
        return `${this._config.url}/api/projects/${this._config.projectId}/data/${this._table}`;
    }

    // ─── Fetch helpers ──────────────────────────────────────────────────────

    private async _fetch(url: string, init?: RequestInit): Promise<Response> {
        return fetch(url, {
            ...init,
            headers: {
                'Content-Type': 'application/json',
                apikey: this._config.apiKey,
                ...init?.headers,
            },
        });
    }

    // ─── Awaitable execution (SELECT) ───────────────────────────────────────

    then<TResult1 = QueryResult<T[]>, TResult2 = never>(
        onfulfilled?: ((value: QueryResult<T[]>) => TResult1 | PromiseLike<TResult1>) | null,
        onrejected?: ((reason: any) => TResult2 | PromiseLike<TResult2>) | null
    ): Promise<TResult1 | TResult2> {
        return this._execute().then(onfulfilled, onrejected);
    }

    private async _execute(): Promise<QueryResult<T[]>> {
        try {
            const url = `${this.baseUrl}?${this.buildParams()}`;
            const res = await this._fetch(url);
            const json = await res.json();

            if (!res.ok) {
                return {
                    data: null,
                    error: { message: json.message || 'Query failed', code: String(res.status) },
                    status: res.status,
                };
            }

            const rows: T[] = json.data?.rows ?? json.data ?? [];
            const count = json.data?.total ?? null;

            if (this._single) {
                if (rows.length === 0) {
                    return { data: null, error: { message: 'Row not found', code: 'PGRST116' }, count: 0 };
                }
                return { data: rows[0] as any, error: null, count: 1 };
            }

            if (this._maybeSingle) {
                return { data: (rows[0] as any) ?? null, error: null, count: rows.length };
            }

            return { data: rows, error: null, count };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    // ─── Mutations ──────────────────────────────────────────────────────────

    async insert(data: Partial<T> | Partial<T>[]): Promise<QueryResult<T[]>> {
        try {
            const url = `${this.baseUrl}?apikey=${this._config.apiKey}`;
            const res = await this._fetch(url, {
                method: 'POST',
                body: JSON.stringify(data),
            });
            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'Insert failed', code: String(res.status) } };
            const rows = json.data?.rows ?? (Array.isArray(json.data) ? json.data : [json.data]);
            return { data: rows, error: null, count: rows.length };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    async update(data: Partial<T>): Promise<QueryResult<T[]>> {
        try {
            const filters: Record<string, any> = {};
            for (const f of this._filters) {
                if (f.operator === 'eq') filters[f.column] = f.value;
            }
            const url = `${this.baseUrl}?apikey=${this._config.apiKey}`;
            const res = await this._fetch(url, {
                method: 'PUT',
                body: JSON.stringify({ data, filters }),
            });
            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'Update failed', code: String(res.status) } };
            const rows = json.data?.rows ?? [];
            return { data: rows, error: null, count: rows.length };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    async upsert(data: Partial<T> | Partial<T>[], _options?: { onConflict?: string }): Promise<QueryResult<T[]>> {
        // MatuDB doesn't have a native upsert endpoint yet — simulate with insert
        return this.insert(data);
    }

    async delete(): Promise<QueryResult<T[]>> {
        try {
            const filters: Record<string, any> = {};
            for (const f of this._filters) {
                if (f.operator === 'eq') filters[f.column] = f.value;
            }
            const url = `${this.baseUrl}?apikey=${this._config.apiKey}`;
            const res = await this._fetch(url, {
                method: 'DELETE',
                body: JSON.stringify({ filters }),
            });
            const json = await res.json();
            if (!res.ok) return { data: null, error: { message: json.message || 'Delete failed', code: String(res.status) } };
            return { data: json.data ?? null, error: null };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }
}
