import type { MatuDBConfig, RealtimeEvent, RealtimePayload } from './types.js';

// socket.io-client is loaded lazily via dynamic import

type RealtimeCallback<T = any> = (payload: RealtimePayload<T>) => void;

interface Subscription<T = any> {
    event: RealtimeEvent;
    callback: RealtimeCallback<T>;
}

/**
 * A channel scoped to a specific table.
 * Mirrors supabase.channel() / postgres_changes pattern.
 *
 * Usage:
 *   db.channel('public:users')
 *     .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'users' }, cb)
 *     .subscribe();
 *
 *   // Shorthand (MatuDB native):
 *   db.from('users').on('INSERT', cb).subscribe();
 */
export class RealtimeChannel<T = any> {
    private _subscriptions: Subscription<T>[] = [];
    private _table: string;
    private _manager: RealtimeManager;
    private _subscribed = false;

    constructor(table: string, manager: RealtimeManager) {
        this._table = table;
        this._manager = manager;
    }

    /**
     * Supabase-compatible: .on('postgres_changes', { event, table }, callback)
     * Also accepts shorthand: .on('INSERT', callback)
     * Also supports 'broadcast' event: .on('broadcast', { event: 'typing' }, cb)
     */
    on(
        eventOrType: RealtimeEvent | 'postgres_changes' | 'broadcast',
        filterOrCallback: any,
        callback?: RealtimeCallback<T>
    ): this {
        if (eventOrType === 'postgres_changes') {
            // Supabase style: .on('postgres_changes', { event: '*', table: 'users' }, cb)
            const filter = filterOrCallback as { event: RealtimeEvent; table?: string; schema?: string };
            const cb = callback!;
            this._subscriptions.push({ event: filter.event ?? '*', callback: cb });
        } else if (eventOrType === 'broadcast') {
            // Broadcast style: .on('broadcast', { event: 'typing' }, cb)
            const filter = filterOrCallback as { event: string };
            const cb = callback!;
            // Using a prefix to distinguish broadcast events in the dispatcher
            this._subscriptions.push({ event: `broadcast:${filter.event}` as any, callback: cb });
        } else {
            // Native style: .on('INSERT', cb)
            const event = eventOrType as RealtimeEvent;
            const cb = filterOrCallback as RealtimeCallback<T>;
            this._subscriptions.push({ event, callback: cb });
        }
        return this;
    }

    send(payload: { event: string;[key: string]: any }): this {
        this._manager._send(this._table, payload.event, payload);
        return this;
    }

    subscribe(statusCallback?: (status: 'SUBSCRIBED' | 'CLOSED' | 'CHANNEL_ERROR', err?: Error) => void): this {
        if (this._subscribed) return this;
        this._subscribed = true;
        this._manager._subscribe(this._table, this._subscriptions);
        statusCallback?.('SUBSCRIBED');
        return this;
    }

    unsubscribe(): void {
        this._manager._unsubscribe(this._table);
        this._subscribed = false;
    }

    /** Internal: dispatch payload to matching listeners */
    _dispatch(payload: RealtimePayload<T>): void {
        const isBroadcast = (payload as any).type === 'broadcast';
        const eventMatch = isBroadcast ? `broadcast:${(payload as any).event}` : payload.action;

        for (const sub of this._subscriptions) {
            if (sub.event === '*' || sub.event === eventMatch) {
                try { sub.callback(payload); } catch { /* no-op */ }
            }
        }
    }
}

/**
 * Realtime manager using Socket.IO.
 * Mirrors supabase.channel() and supabase.removeChannel().
 */
export class RealtimeManager {
    private _config: MatuDBConfig;
    private _socket: any | null = null; // socket.io-client Socket
    private _channels: Map<string, RealtimeChannel> = new Map();
    private _pendingSubscriptions: Map<string, Subscription[]> = new Map();

    constructor(config: MatuDBConfig) {
        this._config = config;
    }

    private async _initSocket(): Promise<void> {
        if (this._socket) return;

        const { io } = await import('socket.io-client');
        this._socket = io(this._config.url, {
            transports: ['websocket', 'polling'],
        });

        this._socket.on('connect', () => {
            // Re-subscribe all channels on reconnect
            this._channels.forEach((_, table) => {
                this._socket.emit('subscribe', {
                    project_id: this._config.projectId,
                    table,
                });
            });
        });

        this._socket.on('change', (payload: RealtimePayload) => {
            const channel = this._channels.get(payload.table);
            channel?._dispatch(payload);
        });

        this._socket.on('broadcast', (payload: { table: string; event: string; payload: any }) => {
            const channel = this._channels.get(payload.table);
            if (channel) {
                channel._dispatch({
                    table: payload.table,
                    action: 'UPDATE' as any, // Dummy action for types
                    data: payload.payload,
                    schema: 'public',
                    type: 'broadcast', // Custom field we use in _dispatch
                    event: payload.event
                } as any);
            }
        });
    }

    /** Create or get a channel for a table. Equivalent to supabase.channel('public:table') */
    channel<T = any>(tableName: string): RealtimeChannel<T> {
        // Strip common prefixes like "public:" for compatibility
        const table = tableName.replace(/^[^:]+:/, '');

        if (!this._channels.has(table)) {
            this._channels.set(table, new RealtimeChannel<T>(table, this));
        }
        return this._channels.get(table) as RealtimeChannel<T>;
    }

    removeChannel(channel: RealtimeChannel): void {
        // Find and remove
        this._channels.forEach((ch, table) => {
            if (ch === channel) {
                this._unsubscribe(table);
                this._channels.delete(table);
            }
        });
    }

    removeAllChannels(): void {
        this._channels.forEach((_, table) => this._unsubscribe(table));
        this._channels.clear();
    }

    /** @internal */
    _send(table: string, event: string, payload: any): void {
        this._socket?.emit('broadcast', {
            project_id: this._config.projectId,
            table,
            event,
            payload
        });
    }

    /** @internal */
    async _subscribe(table: string, _subscriptions: Subscription[]): Promise<void> {
        await this._initSocket();
        this._socket?.emit('subscribe', {
            project_id: this._config.projectId,
            table,
        });
    }

    /** @internal */
    _unsubscribe(table: string): void {
        this._socket?.emit('unsubscribe', {
            project_id: this._config.projectId,
            table,
        });
    }
}
