import type { MatuDBConfig, QueryResult, MatuDBError } from './types.js';

function toError(err: unknown): MatuDBError {
    if (err instanceof Error) return { message: err.message };
    return { message: 'Unknown error' };
}

/**
 * SQL / RPC execution module — mirrors supabase.rpc()
 *
 * Usage:
 *   const { data, error } = await db.rpc('SELECT * FROM users WHERE active = true');
 *
 *   // With params (using positional replacements like $1):
 *   const { data, error } = await db.rpc('SELECT * FROM products WHERE price > $1', { 1: 100 });
 */
export class RpcManager {
    private _config: MatuDBConfig;
    private _accessToken: (() => string | null) | null = null;

    constructor(config: MatuDBConfig, getToken?: () => string | null) {
        this._config = config;
        this._accessToken = getToken ?? null;
    }

    private _baseUrl(): string {
        return `${this._config.url}/api/projects/${this._config.projectId}/sql`;
    }

    private _headers(): Record<string, string> {
        const headers: Record<string, string> = {
            'Content-Type': 'application/json',
            apikey: this._config.apiKey,
        };

        const token = this._accessToken?.();
        if (token) headers['Authorization'] = `Bearer ${token}`;

        return headers;
    }

    /**
     * Execute a raw SQL query.
     * @param query  SQL query string
     * @param _params Named/positional params (optional, for future support)
     */
    async execute<T = any>(query: string, _params?: Record<string, any>): Promise<QueryResult<T[]>> {
        try {
            const res = await fetch(this._baseUrl(), {
                method: 'POST',
                headers: this._headers(),
                body: JSON.stringify({ query }),
            });

            const json = await res.json();

            if (!res.ok) {
                return {
                    data: null,
                    error: { message: json.message || 'SQL execution failed', code: String(res.status) },
                    status: res.status,
                };
            }

            const rows: T[] = json.data?.rows ?? json.data ?? [];
            return { data: rows, error: null, count: rows.length, status: 200 };
        } catch (err) {
            return { data: null, error: toError(err) };
        }
    }

    /**
     * Supabase-compatible rpc() alias.
     * In Supabase, rpc() calls stored procedures. Here it runs raw SQL.
     */
    async call<T = any>(query: string, params?: Record<string, any>): Promise<QueryResult<T[]>> {
        return this.execute<T>(query, params);
    }
}
